\label{lem:Linfty}
Assume that $N\geqslant2$ and
\begin{equation}
\label{q:maximum}
q>1+\frac{1}{N-1},
\qquad\text{or equivalently}\qquad
\frac{1}{q-1}<N-1.
\end{equation}
Let $\Omega\subset\mathbb{R}^N$ be a bounded domain with $C^2$ boundary,
and let
\(
U_0=e^\Delta u_0,
\)
where $u_0$ is given by \eqref{u0}. Let
$\psi\in W^{1,\infty}(\mathbb{R})$ be arbitrary.
Suppose that $U\in W^{1,2}(\Omega)$ is a weak solution of
\begin{equation}
\label{U:bounded}
-\Delta U-\frac{x}{2}\cdot\nabla U- \frac{1}{2(q-1)}U
+
\partial_{x_1}\psi(U)=0
\qquad\text{in }\Omega,
\end{equation}
with boundary condition
\begin{equation}
\label{U:boundary}
U=U_0
\qquad\text{on }\partial\Omega
\end{equation}
in the sense of traces. Then
\begin{equation}
\label{U:Linfty}
\|U\|_{L^\infty(\Omega)}
\leqslant C(N,q,U_0),
\end{equation}
where the constant is independent of $\Omega$ and $\psi$.

\label{lem:uniform:Linfty:N2:q2}
Let $N=2$, $q=2$, and let $u_0$ satisfy \eqref{u0}.
Set
\(
U_0=e^\Delta u_0.
\)
Let $\psi_A$ be the truncated nonlinearity defined in
\eqref{psi1}, with $A>0$, and let $B_k=B(0,k)$.
Fix $p\in(1,2)$ and suppose that
$V_k\in W^{1,p}_0(B_k)$ is a weak solution of
\begin{equation}
\label{endpoint:N2:q2:bounded}
\begin{aligned}
-\Delta V_k-\frac{x}{2}\cdot\nabla V_k
-\frac12 V_k
+\partial_{x_1}\psi_A(V_k+U_0)&=0
&&\text{in }B_k,\\
V_k&=0
&&\text{on }\partial B_k.
\end{aligned}
\end{equation}
Then
\begin{equation}
\label{endpoint:N2:q2:W1p}
\|V_k\|_{W^{1,p}(B_k)}
\leqslant C(p,U_0),
\end{equation}
where the constant is independent of both $k$ and $A$.

Consequently, if $V$ is the whole-space solution constructed
in Theorem~\ref{existence_I} as a limit of the solutions $V_k$,
then
\begin{equation}
\label{endpoint:N2:q2:Linfty}
\|V\|_{L^\infty(\mathbb{R}^2)}
\leqslant C(U_0),
\end{equation}
where the constant is independent of $A$.

\label{lem:heat:1}
Assume $q>1+1/N$. The function \eqref{u:A} with initial datum
\eqref{u0} is smooth for $t>0$, bounded in $x$, and has the
self-similar form
\begin{equation}\label{self:u:A}
u(x,t)= t^{-\frac{1}{2(q-1)}}U_0\left(\frac{x}{\sqrt{t}}\right), 
\end{equation}
where 
\begin{equation}\label{U0_form}
U_0(x)\equiv(e^\Delta u_0)(x)=\int_{\mathbb{R}^N} G(x-y,1)u_0(y)\,\mathrm d y
\end{equation}
solves the elliptic equation
\begin{equation}\label{eq:U0:A}
-\Delta U_0-\tfrac{1}{2}x\cdot\nabla U_0
-\tfrac{1}{2(q-1)}U_0=0
\qquad\text{in }\mathbb{R}^N.
\end{equation}

\label{heat_L}
Let $U_0=e^\Delta u_0$ be defined by equation \eqref{U0_form} with initial datum 
$u_0$ satisfying \eqref{u0}, and assume $q>1+1/N$. There is a
constant $C_0=C_0(q,N,\|C\|_\infty)>0$ such that
\begin{equation*}
\left|e^{\Delta }u_0(x) \right| +\left|\nabla e^{\Delta }u_0(x)\right| \leqslant \frac{C_0}{1+|x|^{\frac{1}{q-1}}}\quad \text{for all}\quad x\in \mathbb{R}^N.
\end{equation*}
In particular,



$ e^{\Delta }u_0 \in L^p(\mathbb{R}^N)$
and
$\nabla e^{\Delta }u_0 \in L^p(\mathbb{R}^N)$
for each  $p\in (N(q-1), \infty ]$. 
If, moreover, $u_0$ is a $C^1$-function outside of the origin then
\begin{equation*}
\left|\nabla e^{\Delta }u_0(x)\right| \leqslant \frac{C_1}{1+|x|^{\frac{1}{q-1}+1}}\quad \text{for all}\quad x\in \mathbb{R}^N.
\end{equation*}

\label{L:A3}
Assume, in addition, that $u_0\in C^1(\mathbb{R}^N\setminus\{0\})$ and
\[
\sup_{x\neq0}|x|^{\frac{1}{q-1}+1}|\nabla u_0(x)|<\infty.
\]
Then
\begin{equation*}
  e^\Delta u_0(x)=u_0(x)+O\left(|x|^{-\frac{1}{q-1}-1}\right) \quad \text{as} \quad |x|\to +\infty.
\end{equation*}
